    "claim_verification_c033": {
      "version": "v7.5",
      "pipeline": [
        {
          "id": "extract",
          "name": "Claim Extraction",
          "prompt": "List atomic factual claims present in the draft message. Exclude pure opinions. Return JSON [{claim, claim_type}].",
          "output_schema": [{"claim": "string", "claim_type": "METRIC|EVENT|QUOTE|ATTRIBUTION|OTHER"}]
        },
        {
          "id": "verify",
          "name": "Claim Verification",
          "method": "For each claim, query sources (final_sources + new targeted queries). Score confidence 0–1.",
          "rubric": {
            "direct": "≥0.90 direct support",
            "supported": "0.75–0.89 supported with inference",
            "weak": "0.60–0.74 weak",
            "speculative": "0.40–0.59 speculative",
            "unsupported": "<0.40 not supported"
          },
          "outputs": [
            {"claim": "string","confidence": "float","evidence_urls": ["string"], "notes": "string"}
          ]
        },
        {
          "id": "filter",
          "name": "Claim Filtering & Hedging",
          "policy": {
            "keep": "confidence ≥ 0.85",
            "hedge": "0.65 ≤ confidence < 0.85 (add qualifiers/timeboxes)",
            "remove": "confidence < 0.65",
            "max_low_conf_kept": 0
          },
          "edits": {
            "hedge_terms": ["as reported in","appears to","indications suggest","recent coverage indicates"],
            "timebox_terms": ["in Q2 2025","as of August 2025","in the last quarter"]
          }
        }
      ],
      "aggregation": {
        "avg_confidence": "mean of kept claims",
        "min_required": 0.80
      },
      "audit": {
        "log_claims": true,
        "log_removed_claims": true,
        "log_hedged_claims": true,
        "log_avg_confidence": true
      }
    },

